schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/portfolio-evm-rollup-method.json",
  "title": "Portfolio EVM rollup",
  "type": "object",
  "required": ["portfolio", "owner", "data_date", "currency", "reporting_period", "executive_review_date", "variance_thresholds", "weighting", "projects", "stale_projects", "aggregate", "executive_summary", "owner_sign_off"],
  "additionalProperties": false,
  "definitions": {
    "handle": {"type": "string", "pattern": "^[a-z-]+:[a-z0-9._-]+$"},
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "timestamp": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?(Z|[+-][0-9]{2}:[0-9]{2})$"},
    "money": {"type": "number"},
    "index": {"type": "number", "minimum": 0},
    "trend": {
      "type": "array",
      "minItems": 3,
      "items": {
        "type": "object",
        "required": ["data_date", "spi", "cpi"],
        "additionalProperties": false,
        "properties": {
          "data_date": {"$ref": "#/definitions/date"},
          "spi": {"$ref": "#/definitions/index"},
          "cpi": {"$ref": "#/definitions/index"}
        }
      }
    },
    "sums": {
      "type": "object",
      "required": ["bac", "pv", "ev", "ac"],
      "properties": {
        "bac": {"$ref": "#/definitions/money"},
        "pv": {"$ref": "#/definitions/money"},
        "ev": {"$ref": "#/definitions/money"},
        "ac": {"$ref": "#/definitions/money"}
      }
    }
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "portfolio": {"type": "string", "minLength": 2},
    "owner": {"$ref": "#/definitions/handle"},
    "data_date": {"$ref": "#/definitions/date"},
    "currency": {"type": "string", "pattern": "^[A-Z]{3}$"},
    "reporting_period": {"type": "string", "enum": ["week", "fortnight", "month"]},
    "executive_review_date": {"$ref": "#/definitions/date"},
    "variance_thresholds": {
      "type": "object",
      "required": ["spi_min", "cpi_min", "cv_pct_of_bac_max", "policy_source"],
      "additionalProperties": false,
      "properties": {
        "spi_min": {"type": "number", "exclusiveMinimum": 0, "maximum": 1},
        "cpi_min": {"type": "number", "exclusiveMinimum": 0, "maximum": 1},
        "cv_pct_of_bac_max": {"type": "number", "exclusiveMinimum": 0, "maximum": 100},
        "policy_source": {"type": "string", "minLength": 3}
      }
    },
    "weighting": {
      "type": "object",
      "required": ["policy"],
      "additionalProperties": false,
      "properties": {
        "policy": {"type": "string", "enum": ["currency-sum", "strategic", "margin", "client-tier"]},
        "policy_document": {"type": "string", "minLength": 3}
      },
      "if": {"properties": {"policy": {"enum": ["strategic", "margin", "client-tier"]}}},
      "then": {"required": ["policy", "policy_document"]}
    },
    "projects": {
      "type": "array",
      "minItems": 3,
      "items": {
        "type": "object",
        "required": ["name", "contract_type", "ev_method", "ledger_file", "ledger_exported_at", "data_date", "currency", "bac", "pv", "ev", "ac", "sv", "cv", "spi", "cpi", "eac", "vac", "eac_formula", "trend"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "minLength": 2},
          "contract_type": {"type": "string", "enum": ["fixed-bid", "time-and-materials", "internal"]},
          "ev_method": {"type": "string", "enum": ["milestone-weight", "0/100", "50/50", "physical-percent-complete", "apportioned-effort", "level-of-effort"]},
          "ledger_file": {"type": "string", "minLength": 3},
          "ledger_exported_at": {"$ref": "#/definitions/timestamp"},
          "data_date": {"$ref": "#/definitions/date"},
          "currency": {"type": "string", "pattern": "^[A-Z]{3}$"},
          "bac": {"type": "number", "exclusiveMinimum": 0},
          "pv": {"$ref": "#/definitions/money"},
          "ev": {"$ref": "#/definitions/money"},
          "ac": {"$ref": "#/definitions/money"},
          "sv": {"$ref": "#/definitions/money"},
          "cv": {"$ref": "#/definitions/money"},
          "spi": {"$ref": "#/definitions/index"},
          "cpi": {"$ref": "#/definitions/index"},
          "eac": {"$ref": "#/definitions/money"},
          "vac": {"$ref": "#/definitions/money"},
          "eac_formula": {"type": "string", "enum": ["BAC/CPI", "AC+(BAC-EV)/(CPI*SPI)", "bottom-up"]},
          "weight": {"type": "number", "exclusiveMinimum": 0},
          "contract_value": {"type": "number", "exclusiveMinimum": 0},
          "implied_margin": {"$ref": "#/definitions/money"},
          "trend": {"$ref": "#/definitions/trend"},
          "variance_narrative": {
            "type": "object",
            "required": ["cause", "corrective_action"],
            "additionalProperties": false,
            "properties": {
              "cause": {"type": "string", "minLength": 12},
              "corrective_action": {"type": "string", "minLength": 12}
            }
          }
        },
        "allOf": [
          {"if": {"properties": {"contract_type": {"const": "fixed-bid"}}},
           "then": {
             "required": ["contract_value", "implied_margin"],
             "properties": {"ev_method": {"enum": ["milestone-weight", "0/100", "50/50"]}}}}
        ]
      }
    },
    "stale_projects": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["name", "bac", "last_data_date", "ledger_exported_at"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "minLength": 2},
          "bac": {"type": "number", "exclusiveMinimum": 0},
          "last_data_date": {"$ref": "#/definitions/date"},
          "ledger_exported_at": {"$ref": "#/definitions/timestamp"}
        }
      }
    },
    "aggregate": {
      "type": "object",
      "required": ["discrete", "loe", "trend"],
      "additionalProperties": false,
      "properties": {
        "discrete": {
          "allOf": [{"$ref": "#/definitions/sums"}],
          "required": ["bac", "pv", "ev", "ac", "spi", "cpi", "eac", "vac"],
          "properties": {
            "spi": {"$ref": "#/definitions/index"},
            "cpi": {"$ref": "#/definitions/index"},
            "eac": {"$ref": "#/definitions/money"},
            "vac": {"$ref": "#/definitions/money"}
          }
        },
        "loe": {"$ref": "#/definitions/sums"},
        "weighted": {
          "type": "object",
          "required": ["spi", "cpi", "eac"],
          "additionalProperties": false,
          "properties": {
            "spi": {"$ref": "#/definitions/index"},
            "cpi": {"$ref": "#/definitions/index"},
            "eac": {"$ref": "#/definitions/money"}
          }
        },
        "trend": {"$ref": "#/definitions/trend"}
      }
    },
    "executive_summary": {
      "type": "object",
      "required": ["bac", "eac", "vac", "fixed_bid_margin_total", "escalated_projects"],
      "additionalProperties": false,
      "properties": {
        "bac": {"$ref": "#/definitions/money"},
        "eac": {"$ref": "#/definitions/money"},
        "vac": {"$ref": "#/definitions/money"},
        "fixed_bid_margin_total": {"$ref": "#/definitions/money"},
        "escalated_projects": {"type": "array", "items": {"type": "string", "minLength": 2}, "uniqueItems": true}
      }
    },
    "owner_sign_off": {
      "type": "object",
      "required": ["signed_by", "signed_at"],
      "additionalProperties": false,
      "properties": {
        "signed_by": {"$ref": "#/definitions/handle"},
        "signed_at": {"$ref": "#/definitions/date"}
      }
    }
  }
}

